from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up.
prime_hub = PrimeHub()
motor = Motor(Port.C, Direction.COUNTERCLOCKWISE)
motor_2 = Motor(Port.D, Direction.CLOCKWISE)
drive_base = DriveBase(motor, motor_2, 56, 128)
back_arm = Motor(Port.A, Direction.COUNTERCLOCKWISE)
front_motor = Motor(Port.E, Direction.CLOCKWISE)

async def main():
    drive_base.use_gyro(True)
    drive_base.settings(straight_speed=500)
    await drive_base.straight(500)
    await drive_base.turn(90)
    await drive_base.straight(60)
    await drive_base.turn(-90)
    await drive_base.straight(140)
    # lift up 1
    await front_motor.run_angle(1000, 360)
    await drive_base.straight(-100)
    # Arm down
    await front_motor.run_angle(1000, -200)
    await drive_base.straight(100)
    # lift up 2
    await front_motor.run_angle(1000, 330)
    # On the way to Kira's mission
    await drive_base.straight(-50)
    await drive_base.turn(90)
    await drive_base.straight(265)
    await drive_base.turn(-90)
    # Starts mission
    await front_motor.run_angle(500, -140)
    await drive_base.straight(50)


run_task(main())